pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 initialBalance, uint256 collectAmt) public {
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        initialBalance = bound(initialBalance, 0, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);

        // Setup: initialize and set MinSum, fund caller
        vm.assume(caller != address(0) && caller != address(c));
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record total balance before
        uint256 totalBefore = c.balances(caller) + address(c).balance;

        // Call Collect with the given amount
        uint256 totalSent = collectAmt; // we send no ETH in Collect call
        bool reverted = false;
        try c.Collect(collectAmt) {
            // success
        } catch {
            reverted = true;
        }

        // Rule: if Collect did not revert, total balance (caller's balance + contract ETH) must not increase beyond original total + sent amount
        if (!reverted) {
            uint256 totalAfter = c.balances(caller) + address(c).balance;
            assertTrue(totalAfter <= totalBefore + totalSent, "Total balance increased beyond ETH sent");
        }
    }
}

