pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount <= type(uint256).max - collectAmount); // prevent overflow in init
        // Set up
        vm.startPrank(caller);
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();
        c.Deposit{value: depositAmount}();
        vm.stopPrank();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Read balance after
        uint256 balanceAfter = c.balances(caller);

        // General rule: the caller's balance in the contract should never increase due to a Collect call
        // (it can stay same if Collect reverted, or decrease if successful)
        assertTrue(balanceAfter <= balanceBefore);
    }
}

