pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 am) public {
        // Bound inputs to avoid overflow/underflow issues
        vm.assume(caller != address(0));
        am = bound(am, 0, 1e18);
        deposit = bound(deposit, 0, 1e18);
        minSum = bound(minSum, 0, 1e18);

        // Set MinSum (can only be set once before initialized)
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, deposit + am);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        uint256 balanceBefore = caller.balance;
        uint256 amToCollect = am;

        // Call Collect
        vm.prank(caller);
        // We don't care if it reverts or not; we just check after
        // Use try/catch to continue regardless of revert
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amToCollect));
        // success is unused; we only check balance change

        uint256 balanceAfter = caller.balance;

        // Rule: caller's balance must not increase (either decreases by exactly am or stays same)
        assertTrue(balanceAfter >= balanceBefore - am && balanceAfter <= balanceBefore);
    }
}

