pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 am) public {
        vm.assume(caller != address(0));
        vm.assume(deposit < type(uint256).max / 2);
        vm.assume(am < type(uint256).max / 2);

        // Set MinSum and initialize
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit funds from caller
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        uint256 balanceBefore = c.balances(caller);

        // Try Collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        uint256 balanceAfter = c.balances(caller);

        // General rule: if the call succeeded, the balance after is never ≥ MinSum if it wasn't already ≥ MinSum before
        // Equivalent: if balanceBefore < minSum, then balanceAfter < minSum
        // If success, balanceBefore >= minSum must hold (reference invariant)
        if (success) {
            assertTrue(balanceBefore >= minSum, "Collect should only succeed when balance >= MinSum");
        }
    }
}

