pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address user) public {
        vm.assume(user != address(0));
        uint256 minSum = 0;
        vm.assume(collectAmount <= depositAmount);
        // initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // get initial balance of user
        uint256 initialBalance = c.balances(user);

        // deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();
        uint256 afterDeposit = c.balances(user);

        // collect
        vm.prank(user);
        c.Collect(collectAmount);
        uint256 afterCollect = c.balances(user);

        // general rule: after collect, balance should be initialBalance + depositAmount - collectAmount (if collect succeeded)
        // In the reference, this holds. In the buggy version, after collect the balance will be negative or unexpectedly low.
        // Since collect only proceeds if balances[msg.sender] >= MinSum && balances[msg.sender] >= _am,
        // and MinSum=0, and we assumed collectAmount <= depositAmount, so it always proceeds.
        // The invariant: after the sequence, the balance is non-negative and equals the expected calculation.
        // But to be robust against revert differences, we wrap Collect in try/catch and check a simpler invariant:
        // The sum of all balances (i.e., total contract balance) equals total deposits minus total collects.
        // However, since we only have one user, we can check the user's balance directly.

        // Simpler: after collect, the balance should be initialBalance + depositAmount - collectAmount (since MinSum=0 and collect succeeds)
        uint256 expectedBalance = initialBalance + depositAmount - collectAmount;
        // In reference: afterCollect == expectedBalance
        // In mutant: afterCollect will be initialBalance - depositAmount - collectAmount (since deposit subtracts)
        // This will be a large negative number (underflow) or just wrong.
        assertTrue(afterCollect == expectedBalance, "Balance invariant broken");
    }
}

