import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Deposit from sender
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Get history length before Collect
        uint256 lenBefore = c.Log().History();

        // Call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get history length after Collect
        uint256 lenAfter = c.Log().History();

        // General rule: if Collect succeeded, history length must have increased by exactly 1
        // If Collect reverted, history length must be unchanged
        assertTrue(
            (success && lenAfter == lenBefore + 1) ||
            (!success && lenAfter == lenBefore)
        );
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

